// 自動生成 — pr/drafts/dv-src/make_figures.py が書き出す。**直接編集しない。**
// 数字の出どころは dv-src/analyze.py（e-Stat の実数から再集計）と
// dv-src/build_preview.py の警察庁定数。作り直すには make_figures.py を再実行する。
//
// ⚠️ 図は SVG のまま置く（文字が入っているので画像にすると読めない）。
// ⚠️ **PC 用とスマホ用の2枚組**。`.pconly` / `.sponly` は journal.css で出し分ける。
//    720幅の viewBox をスマホに入れると font-size 12 が 5.5px になるため
//    （→ 記憶 mobile-check-before-ship）。
// ⚠️ 色は `figures.css` が `.dvfig` にスコープして配る。系列色はライトとダークで
//    別の値を当てる必要があるので、SVG に直書きしていない。
import "./figures.css";

/** 図の共通の器。dash 層は影も角丸も付けず、上のヘアラインと余白だけで区切る。 */
function Fig({
  n,
  title,
  src,
  caption,
  children,
}: {
  n: string;
  title: string;
  src: string;
  caption?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <figure className="fig dvfig rv">
      <div className="hd">
        <div>
          <span className="lbl">FIG {n}</span>
          <div className="ttl">{title}</div>
        </div>
        <span className="src">{src}</span>
      </div>
      {children}
      {caption ? <figcaption>{caption}</figcaption> : null}
    </figure>
  );
}


